-- CulinaLinkTX Verified Professional reference migration. Apply only through approved PostgreSQL migration/change control.
CREATE SCHEMA IF NOT EXISTS compliance;
CREATE TABLE IF NOT EXISTS compliance.verification_memberships(id uuid PRIMARY KEY,provider_id uuid NOT NULL,membership_tier text NOT NULL CHECK(membership_tier IN ('VERIFIED_PROFESSIONAL','VERIFIED_PROFESSIONAL_PLUS')),status text NOT NULL CHECK(status IN ('SUBMITTED','UNDER_REVIEW','NEEDS_INFORMATION','VERIFIED','EXPIRING','EXPIRED','DECLINED','SUSPENDED','REVOKED')),submitted_at timestamptz NOT NULL DEFAULT now(),verified_at timestamptz,valid_through timestamptz,renewal_of uuid,decision_reason text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS compliance.verification_checks(id uuid PRIMARY KEY,membership_id uuid NOT NULL REFERENCES compliance.verification_memberships(id),requirement text NOT NULL,status text NOT NULL CHECK(status IN ('PENDING','VERIFIED','NOT_REQUIRED','NEEDS_INFORMATION','REJECTED')),evidence_source text,evidence_reference text,review_note text,reviewer_id text,reviewed_at timestamptz,UNIQUE(membership_id,requirement));
CREATE TABLE IF NOT EXISTS compliance.verification_events(id bigserial PRIMARY KEY,membership_id uuid NOT NULL REFERENCES compliance.verification_memberships(id),action text NOT NULL,from_status text,to_status text,reason text,actor_id text,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS verification_memberships_provider_idx ON compliance.verification_memberships(provider_id,status);CREATE INDEX IF NOT EXISTS verification_memberships_expiry_idx ON compliance.verification_memberships(status,valid_through);